[CmdletBinding()]param([Parameter(Position=0)][ValidateSet('full','assess','sites','lists','plan','doctor','help')][string]$Command='full',[string]$OutputPath=(Join-Path $PWD ('s8-sharepoint-modernizer-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))),[int]$StaleDays=365,[int]$LargeListThreshold=5000,[string]$FixturePath,[switch]$InstallDependencies)
Import-Module (Join-Path $PSScriptRoot 'S8.M365.psm1') -Force;Initialize-S8Runtime
if($Command-eq'help'){Write-Output 's8spmodern full|assess|sites|lists|plan [-FixturePath fixture.json] [-StaleDays 365] [-LargeListThreshold 5000]';exit};if($Command-eq'doctor'){[pscustomobject]@{PowerShell=$PSVersionTable.PSVersion.ToString();Fixture=[bool]$FixturePath}|Format-List;exit}
$ev=New-Object Collections.ArrayList;$ctx=if($FixturePath){[pscustomobject]@{TenantId='fixture';Account='offline'}}else{Connect-S8Graph @('Sites.Read.All','Directory.Read.All') -InstallDependencies:$InstallDependencies};$sites=Invoke-S8SourceCollection 'SharePoint sites' 'sites' $FixturePath {Get-S8GraphCollection 'https://graph.microsoft.com/v1.0/sites?search=*'} $ev;$allLists=if($FixturePath){Invoke-S8SourceCollection 'Lists' 'lists' $FixturePath {$null} $ev}else{@()};$siteRows=@();$listRows=@();foreach($site in $sites){$lists=if($FixturePath){@($allLists|? siteId-eq$site.id)}else{Invoke-S8Collection "Lists $($site.id)" {Get-S8GraphCollection "https://graph.microsoft.com/v1.0/sites/$($site.id)/lists"} $ev};$large=@($lists|?{[int]$_.itemCount-ge$LargeListThreshold});foreach($l in $lists){$listRows+=[pscustomobject]@{Site=$site.webUrl;List=$l.displayName;Template=$l.template;ItemCount=$l.itemCount;Large=[bool]([int]$l.itemCount-ge$LargeListThreshold)}};$days=if($site.lastModifiedDateTime){[math]::Floor(((Get-Date)-[datetime]$site.lastModifiedDateTime).TotalDays)}else{$null};$flags=@();if($days-ge$StaleDays){$flags+='Stale site'};if($large.Count){$flags+="$($large.Count) large lists"};$siteRows+=[pscustomobject]@{Site=$site.displayName;Url=$site.webUrl;DaysSinceModified=$days;Lists=$lists.Count;LargeLists=$large.Count;ModernizationFlags=($flags-join'; ');Priority=if($large.Count){'High'}elseif($days-ge$StaleDays){'Medium'}else{'Low'}}};$plan=@($siteRows|? ModernizationFlags|%{[pscustomobject]@{Priority=$_.Priority;Site=$_.Site;Url=$_.Url;Finding=$_.ModernizationFlags;RecommendedAction=if($_.LargeLists){'Review indexing, views, migration constraints and information architecture'}else{'Confirm ownership and archive or modernize'};ChangeMode='Plan only'}});New-Item -ItemType Directory $OutputPath -Force|Out-Null;Export-S8Data $OutputPath 'site-assessment' $siteRows;Export-S8Data $OutputPath 'list-assessment' $listRows;Export-S8Data $OutputPath 'modernization-plan' $plan;Complete-S8Run $OutputPath 'm365-sharepoint-modernizer' $Command $ctx $ev $(if($FixturePath){'Offline fixture'}else{'Live Graph'});Write-S8Report $OutputPath 'System 8 · SharePoint Modernizer' ([ordered]@{'Plan'=$plan;'Sites'=$siteRows;'Lists'=$listRows;'Evidence'=@($ev)});[pscustomobject]@{Output=$OutputPath;Sites=$siteRows.Count;PlanItems=$plan.Count;Mode='Read-only'}
